    seen=np.zeros_like(m,bool); best=None
    for y in range(144):
        for x in range(256):
            if m[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=1; pts=[]
                while q:
                    cy,cx=q.popleft(); pts.append((cy,cx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<144 and 0<=nx<256 and m[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=1; q.append((ny,nx))
                if best is None or len(pts)>len(best): best=pts
    return best
for t in range(96):
    p=comp(diff[t]>40)
